def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 base=ROOT/'versions/v0141-51ff11b9';old=(base/'actors.c').read_text();s=(ROOT/'megadrive/src/actors.c').read_text()
